          value={draft}
          onChange={setDraft}
          onSubmit={submit}
          onCommand={runCommand}
          streaming={streaming}
          onStop={stopStreaming}
          inputRef={inputRef}
          attachments={attachments}
          onAttachFiles={(files) => void attachFiles(files)}
          onRemoveAttachment={removeAttachment}
          attachmentError={attachError}
        />
      </div>
    </section>
  );
